window.CubeApiDocs.define("api-Audio_Processing-语音情绪识别",{"id":"api-Audio_Processing-语音情绪识别","versions":[{"version":"1.0.0","toc":[{"id":"overview","title":"用途与调用说明"},{"id":"request-example","title":"请求示例"},{"id":"parameters","title":"路径与通用参数"},{"id":"body","title":"请求体参数"},{"id":"success","title":"成功响应"},{"id":"errors","title":"错误与处理"}],"html":"\u003carticle data-api-id=\"api-Audio_Processing-语音情绪识别\">\u003cheader class=\"article-header\">\u003cp class=\"eyebrow\">音频处理 · v1.0.0\u003c/p>\u003ch1 tabindex=\"-1\">语音情绪识别\u003c/h1>\u003cdiv class=\"endpoint\">\u003cspan class=\"method post\">POST\u003c/span>\u003ccode>/aigc/speech/emotion/:token\u003c/code>\u003cbutton type=\"button\" data-copy=\"path\" aria-label=\"复制接口路径\">复制路径\u003c/button>\u003c/div>\u003c/header>\u003csection class=\"doc-section\" id=\"overview\">\u003ch2>用途与调用说明\u003c/h2>\u003cp>识别整段语音的情绪倾向。使用前先通过文件接口上传语音文件并获得文件码。\u003cbr/> 该接口在提交任务后立即返回，结果按文件码缓存，使用查询接口获取结果。\u003c/p>\u003c/section>\u003csection class=\"doc-section\" id=\"request-example\">\u003ch2>请求示例\u003c/h2>\u003cdiv class=\"example\">\u003ch3>请求示例\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"fileCode\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"CnDtDLwrEvDsREVcxWJoPMVNcUsErxsvkUFdaLMVWpRausGrOZpHrPdmToSGynTy\"\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"parameters\">\u003ch2>路径与通用参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Parameter\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>token\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>授权令牌。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"body\">\u003ch2>请求体参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"字段说明\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>fileCode\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>语音文件的文件码。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>reset\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>设置为 \u003ccode>true\u003c/code> 时忽略该文件已有的识别结果并重新识别。默认值：\u003ccode>false\u003c/code>。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"success\">\u003ch2>成功响应\u003c/h2>\u003cdiv class=\"example\">\u003ch3>应答示例\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>HTTP/\u003cspan class=\"token number\">1.1\u003c/span> \u003cspan class=\"token number\">200\u003c/span> OK\n\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"fileCode\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"CnDtDLwrEvDsREVcxWJoPMVNcUsErxsvkUFdaLMVWpRausGrOZpHrPdmToSGynTy\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"stateCode\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">0\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"timestamp\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">1774944939693\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"result\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token punctuation\">{\u003c/span>\n        \u003cspan class=\"token property\">\"elapsed\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">812\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"emotion\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token punctuation\">{\u003c/span>\n            \u003cspan class=\"token property\">\"name\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"Sad\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n            \u003cspan class=\"token property\">\"primaryWord\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"悲伤\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n            \u003cspan class=\"token property\">\"secondaryWord\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"伤心\"\u003c/span>\n        \u003cspan class=\"token punctuation\">}\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"score\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">0.8002817\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"duration\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">194.95\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"file\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token punctuation\">{\u003c/span> ... \u003cspan class=\"token punctuation\">}\u003c/span>\n    \u003cspan class=\"token punctuation\">}\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003cbutton class=\"expand-code\" type=\"button\" aria-expanded=\"false\" data-expand-code>展开完整示例\u003c/button>\u003c/div>\u003c/div>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Success 200\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>fileCode\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>语音文件的文件码。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>stateCode\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003c/td>\u003ctd>\u003cp>操作状态码。\u003ccode>7\u003c/code> 正在处理，\u003ccode>0\u003c/code> 处理完成。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>timestamp\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003c/td>\u003ctd>\u003cp>提交任务执行时的时间戳。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>result\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Object\u003c/code>\u003c/td>\u003ctd>\u003cp>识别结果。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>result.elapsed\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003c/td>\u003ctd>\u003cp>以毫秒为单位的识别耗时。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>result.emotion\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Object\u003c/code>\u003c/td>\u003ctd>\u003cp>情绪描述。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:2\">\u003ccode>result.emotion.name\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>情绪名称。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:2\">\u003ccode>result.emotion.primaryWord\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>情绪主描述词。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:2\">\u003ccode>result.emotion.secondaryWord\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>情绪次描述词。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>result.score\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003c/td>\u003ctd>\u003cp>情绪得分。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>result.duration\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003c/td>\u003ctd>\u003cp>语音时长，单位：秒。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:1\">\u003ccode>result.file\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Object\u003c/code>\u003c/td>\u003ctd>\u003cp>语音文件标签。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"errors\">\u003ch2>错误与处理\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Error 4xx\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>400\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>系统故障。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>401\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>令牌无效。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>403\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>参数格式错误。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003c/article>"}]});
